// See: https://z-wave.me/manual/z-way/Command_Class_Reference.htm
switch (path[0]) {
    case "32": // common binary sensor
        res.payload.unit = 'b';
        res.payload.name = 'Alert';
    case "37": // common binary switch
        res.payload.unit = 'b';
        res.payload.name = 'Switch';
        break;
    case "38": // common level switch
        switch (path[2]) {
            case "On":
                res.payload.unit = 'b';
                res.payload.name = 'Switch on';
                break;
            case "Off":
                res.payload.unit = 'b';
                res.payload.name = 'Switch off';
                break;
            case "currentValue":
                res.payload.unit = '%';
                res.payload.name = 'Level switch state';
                break;
            case "targetValue":
                res.payload.unit = '%';
                res.payload.name = 'Level switch target';
                break;
            case "Up":
